<?php
function page_batches(array $u):void {
 $manager=is_manager($u);$types=rows('SELECT id,name,examples FROM raw_types');$batches=$manager?rows("SELECT b.*,s.legal_name,r.name raw_name,(SELECT COALESCE(SUM(a.quantity),0) FROM allocations a WHERE a.batch_id=b.id AND a.status<>'rejected') reserved FROM raw_batches b JOIN suppliers s ON s.id=b.supplier_id JOIN raw_types r ON r.id=b.raw_type_id ORDER BY b.id DESC"):rows("SELECT b.*,s.legal_name,r.name raw_name,(SELECT COALESCE(SUM(a.quantity),0) FROM allocations a WHERE a.batch_id=b.id AND a.status<>'rejected') reserved FROM raw_batches b JOIN suppliers s ON s.id=b.supplier_id JOIN raw_types r ON r.id=b.raw_type_id WHERE b.supplier_id=? ORDER BY b.id DESC",[$u['supplier_id']]);
 if(!$manager): ?><div class="panel panel-pad mb-4 form-card"><h5>Catat batch limbah kelapa</h5><p class="helper">Bahan mentah masuk terlebih dahulu; alokasi koperasi dilakukan oleh pusat.</p><form method="post" class="row g-3"><?=csrf_input()?><input type="hidden" name="action" value="new_batch"><div class="col-md-5"><?php select_field('Jenis limbah','raw_type_id',array_column($types,'name','id'));?></div><div class="col-md-3"><?php field('Berat (kg)','quantity','number','','required step="0.01" min="0.01"');?></div><div class="col-md-4"><?php field('Catatan','notes','text','','');?></div><div class="col-12"><button class="btn btn-coco">+ Simpan batch pasokan</button></div></form></div><?php endif; ?>
<div class="panel"><div class="panel-pad section-title mb-0"><h5>Daftar batch limbah · <?=count($batches)?></h5><span class="chip">Satuan standar: kg</span></div><div class="table-responsive"><table class="table"><thead><tr><th>Kode batch</th><th>PT sumber</th><th>Jenis</th><th>Qty awal</th><th>Dialokasikan</th><th>Sisa</th><th>Tanggal</th></tr></thead><tbody><?php foreach($batches as $b):?><tr><td class="fw-bold"><?=e($b['batch_code'])?></td><td><?=e($b['legal_name'])?></td><td><?=e($b['raw_name'])?></td><td><?=number($b['quantity'])?> kg</td><td><?=number($b['reserved'])?> kg</td><td><strong><?=number((float)$b['quantity']-(float)$b['reserved'])?> kg</strong></td><td><?=e(substr($b['created_at'],0,10))?></td></tr><?php endforeach;?></tbody></table><?php if(!$batches)table_empty('Batch limbah belum dicatat.');?></div></div>
<?php }
